 @Override public void onCreate(Bundle state){MantraTheme.activity(this);super.onCreate(state);setResult(RESULT_CANCELED);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);
  try{if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID&&!CustomWidgetProvider.owns(this,widgetId)){finish();return;}plan=state!=null?new JSONObject(state.getString("plan")):widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID?CustomWidgetStore.widget(this,widgetId):null;if(plan==null)plan=CustomWidgetStore.defaults();if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){plan.put("size",CustomWidgetProvider.size(this,widgetId));trimActions();}render();}catch(Exception e){error(e);finish();}}
 @Override protected void onSaveInstanceState(Bundle state){try{state.putString("plan",plan.toString());}catch(Exception ignored){}super.onSaveInstanceState(state);}
 private void error(Exception e){Toast.makeText(this,e.getMessage()==null?"Could not update widget":e.getMessage(),Toast.LENGTH_LONG).show();}
 private ArrayList<String> actions(){ArrayList<String> result=new ArrayList<>();JSONArray a=plan.optJSONArray("actions");if(a!=null)for(int i=0;i<a.length();i++)result.add(a.optString(i));return result;}
 private void trimActions()throws Exception{ArrayList<String> a=actions();while(a.size()>CustomWidgetStore.capacity(plan.getString("size")))a.remove(a.size()-1);plan.put("actions",new JSONArray(a));}
 private Spinner spinner(String[] values,LinearLayout parent){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));parent.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
 private void render()throws Exception{
  rendering=true;ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(12),dp(22),dp(32));root.setBackgroundColor(MantraTheme.color(this,0xffffffff));scroll.addView(root);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(scroll);
  button("‹ Back",root,this::finish);root.addView(text(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Custom widget":"Edit custom widget",27));
  button("Load a saved layout",root,this::loadLayout);if(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID)button("Manage home-screen widgets",root,this::manage);
  root.addView(heading("Size · columns × rows",13));sizes=spinner(Arrays.stream(CustomWidgetStore.SIZES).map(s->s.replace("x"," × ")).toArray(String[]::new),root);sizes.setContentDescription("Widget size");sizes.setSelection(Arrays.asList(CustomWidgetStore.SIZES).indexOf(plan.getString("size")));sizes.setEnabled(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID);
  TextView help=text(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Your launcher controls final placement and cell dimensions. A 1 × 1 widget holds one action.":"The home-screen size stays the same. Change this widget’s actions, order and appearance below.",12);help.setTextColor(muted());root.addView(help);
  root.addView(heading("Widget type",16));types=spinner(new String[]{"Shortcut buttons","Money summary"},root);types.setContentDescription("Widget type");types.setSelection("money".equals(plan.optString("type"))?1:0);
  moneySettings=new LinearLayout(this);moneySettings.setOrientation(LinearLayout.VERTICAL);root.addView(moneySettings);moneySettings.addView(heading("Choose money figures",16));moneyViews=spinner(new String[]{"Today’s summary","Today’s expenses","Today’s income","Today’s savings","This month’s summary","This month’s expenses","This month’s income","This month’s savings"},moneySettings);moneyViews.setContentDescription("Money figures");moneyViews.setSelection(Arrays.asList(CustomWidgetStore.MONEY_VIEWS).indexOf(plan.getString("moneyView")));moneySettings.addView(text("Full summaries use 3 x 3. Individual figures use 2 x 1 (width x height). Figures come from the diary currently open in MANTRA and refresh when the app syncs.",12));
  shortcutSettings=new LinearLayout(this);shortcutSettings.setOrientation(LinearLayout.VERTICAL);root.addView(shortcutSettings);
  shortcutSettings.addView(heading("Choose buttons",16));checks=new CheckBox[4];ArrayList<String> selected=actions();for(int i=0;i<4;i++){final String action=CustomWidgetStore.ACTIONS[i];CheckBox check=new CheckBox(this);checks[i]=check;check.setText(CustomWidgetStore.LABELS[i]);check.setTextColor(ink());check.setChecked(selected.contains(action));shortcutSettings.addView(check);check.setOnCheckedChangeListener((b,on)->{if(rendering)return;try{ArrayList<String> a=actions();if(on&&!a.contains(action)){if(a.size()>=CustomWidgetStore.capacity(plan.getString("size"))){rendering=true;check.setChecked(false);rendering=false;Toast.makeText(this,"Choose up to "+CustomWidgetStore.capacity(plan.getString("size"))+" buttons for this size",Toast.LENGTH_SHORT).show();return;}a.add(action);}else if(!on)a.remove(action);plan.put("actions",new JSONArray(a));refreshPreview();}catch(Exception e){error(e);}});}
  shortcutSettings.addView(heading("Button order",16));order=new LinearLayout(this);order.setOrientation(LinearLayout.VERTICAL);shortcutSettings.addView(order);
  appearanceSettings=new LinearLayout(this);appearanceSettings.setOrientation(LinearLayout.VERTICAL);root.addView(appearanceSettings);appearanceSettings.addView(heading("Appearance",16));String[] appearances={"Follow app theme","Light","Dark","Transparent"};appearance=spinner(appearances,appearanceSettings);appearance.setContentDescription("Widget appearance");appearance.setSelection(Arrays.asList(new String[]{"app","light","dark","transparent"}).indexOf(plan.getString("appearance")));
  root.addView(heading("Preview",16));preview=new LinearLayout(this);preview.setOrientation(LinearLayout.VERTICAL);preview.setPadding(dp(8),dp(8),dp(8),dp(8));root.addView(preview,new LinearLayout.LayoutParams(-1,dp(220)));
  button("Save layout",root,()->{try{syncName();CustomWidgetStore.saveLayout(this,plan);Toast.makeText(this,"Layout saved on this device",Toast.LENGTH_SHORT).show();}catch(Exception e){error(e);}});
  Button save=button(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Add to home screen":"Save widget",root,this::finishWidget);android.graphics.drawable.GradientDrawable fill=new android.graphics.drawable.GradientDrawable();fill.setColor(0xff246841);fill.setCornerRadius(dp(10));save.setBackground(fill);save.setTextColor(Color.WHITE);save.setGravity(Gravity.CENTER);
  sizes.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering||"money".equals(plan.optString("type")))return;try{plan.put("size",CustomWidgetStore.SIZES[index]);int before=actions().size();trimActions();rendering=true;for(int i=0;i<4;i++)checks[i].setChecked(actions().contains(CustomWidgetStore.ACTIONS[i]));rendering=false;if(before>actions().size())Toast.makeText(CustomWidgetConfigureActivity.this,"Kept the first "+actions().size()+" buttons to fit this size",Toast.LENGTH_SHORT).show();refreshPreview();}catch(Exception e){error(e);}}});
  appearance.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("appearance",new String[]{"app","light","dark","transparent"}[index]);refreshPreview();}catch(Exception e){error(e);}}});
  types.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{if(index==1&&!"money".equals(plan.optString("type")))plan.put("shortcutSize",plan.getString("size"));if(index==0&&"money".equals(plan.optString("type")))plan.put("size",plan.optString("shortcutSize","2x2"));plan.put("type",index==1?"money":"shortcuts");if(index==1){plan.put("uid",NativeDiaryStore.uid(CustomWidgetConfigureActivity.this));}refreshPreview();}catch(Exception e){error(e);}}});
  moneyViews.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("moneyView",CustomWidgetStore.MONEY_VIEWS[index]).put("uid",NativeDiaryStore.uid(CustomWidgetConfigureActivity.this));refreshPreview();}catch(Exception e){error(e);}}});
  rendering=false;refreshPreview();
 }
 private void syncName()throws Exception{plan.put("name","");if("money".equals(plan.optString("type")))plan.put("uid",NativeDiaryStore.uid(this));plan=CustomWidgetStore.validate(plan);}
 private void refreshPreview()throws Exception{
  boolean money="money".equals(plan.optString("type"));if(money){plan.put("size",CustomWidgetStore.moneySize(plan.optString("moneyView")));}rendering=true;sizes.setSelection(Arrays.asList(CustomWidgetStore.SIZES).indexOf(plan.getString("size")));sizes.setEnabled(!money&&widgetId==AppWidgetManager.INVALID_APPWIDGET_ID);appearanceSettings.setVisibility(money?View.VISIBLE:View.GONE);rendering=false;shortcutSettings.setVisibility(money?View.GONE:View.VISIBLE);moneySettings.setVisibility(money?View.VISIBLE:View.GONE);
  order.removeAllViews();ArrayList<String> a=actions();for(String action:a){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(56));TextView label=text(CustomWidgetStore.label(action),13);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));ImageView handle=new ImageView(this);handle.setImageResource(android.R.drawable.ic_menu_sort_by_size);handle.setColorFilter(MantraTheme.dark(this)?0xffb3dfc0:0xff246841);handle.setPadding(dp(12),dp(12),dp(12),dp(12));handle.setContentDescription("Drag to reorder "+CustomWidgetStore.label(action));row.addView(handle,new LinearLayout.LayoutParams(dp(48),dp(48)));View.OnLongClickListener drag=v->row.startDragAndDrop(ClipData.newPlainText("MANTRA widget action",action),new View.DragShadowBuilder(row),action,0);row.setOnLongClickListener(drag);handle.setOnTouchListener((v,event)->{if(event.getAction()==android.view.MotionEvent.ACTION_DOWN)return drag.onLongClick(v);return true;});row.setOnDragListener((v,event)->{if(!(event.getLocalState() instanceof String))return false;switch(event.getAction()){case DragEvent.ACTION_DRAG_STARTED:return true;case DragEvent.ACTION_DRAG_ENTERED:row.setAlpha(0.55f);return true;case DragEvent.ACTION_DRAG_EXITED:case DragEvent.ACTION_DRAG_ENDED:row.setAlpha(1f);return true;case DragEvent.ACTION_DROP:try{ArrayList<String> sorted=actions();int from=sorted.indexOf((String)event.getLocalState()),to=sorted.indexOf(action);if(from>=0&&to>=0&&from!=to){String moved=sorted.remove(from);sorted.add(to,moved);plan.put("actions",new JSONArray(sorted));refreshPreview();}row.setAlpha(1f);return true;}catch(Exception e){error(e);return false;}default:return true;}});row.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.addAction(new android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction(0x01020001,"Move up"));info.addAction(new android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction(0x01020002,"Move down"));}@Override public boolean performAccessibilityAction(View host,int id,Bundle args){if(id==0x01020001||id==0x01020002){move(actions().indexOf(action),id==0x01020001?-1:1);return true;}return super.performAccessibilityAction(host,id,args);}});order.addView(row);}
  preview.removeAllViews();boolean dark=CustomWidgetProvider.dark(this,plan);preview.setBackgroundColor(!money?Color.WHITE:"transparent".equals(plan.optString("appearance"))?MantraTheme.color(this,0xffeae8de):dark?0xff182126:Color.WHITE);
  if(!money&&a.isEmpty()){preview.addView(text("Choose at least one button",15));return;}JSONObject snapshot=new JSONObject(plan.toString());String[] dims=plan.getString("size").split("x");int x=Integer.parseInt(dims[0]),y=Integer.parseInt(dims[1]);int maximum=getResources().getDisplayMetrics().widthPixels-dp(60);float scale=Math.min(maximum/(float)dp(x*70),dp(300)/(float)dp(y*70));int width=(int)(dp(x*70)*scale),height=(int)(dp(y*70)*scale);Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,Math.round(height/getResources().getDisplayMetrics().density));options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,Math.round(width/getResources().getDisplayMetrics().density));View example=CustomWidgetProvider.views(this,widgetId,snapshot,options).apply(this,preview);example.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);disable(example);preview.setGravity(Gravity.CENTER);preview.getLayoutParams().height=height+dp(16);preview.addView(example,new LinearLayout.LayoutParams(width,height));
 }
 private void disable(View v){v.setEnabled(false);v.setClickable(false);v.setFocusable(false);if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++)disable(group.getChildAt(i));}}
 private void move(int index,int step){try{ArrayList<String> a=actions();int next=index+step;if(next<0||next>=a.size())return;Collections.swap(a,index,next);plan.put("actions",new JSONArray(a));refreshPreview();}catch(Exception e){error(e);}}
 private void loadLayout(){JSONObject saved=CustomWidgetStore.layouts(this);ArrayList<String> ids=new ArrayList<>(),labels=new ArrayList<>();java.util.Iterator<String> keys=saved.keys();while(keys.hasNext()){String id=keys.next();JSONObject p=saved.optJSONObject(id);if(p!=null){ids.add(id);labels.add(("money".equals(p.optString("type"))?"Money":"Shortcuts")+" · "+p.optString("size"));}}if(ids.isEmpty()){Toast.makeText(this,"No saved layouts yet",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Saved layouts").setItems(labels.toArray(new String[0]),(d,index)->{try{plan=CustomWidgetStore.validate(saved.getJSONObject(ids.get(index)));if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){plan.put("size",CustomWidgetProvider.size(this,widgetId));trimActions();}if("money".equals(plan.optString("type")))plan.put("uid",NativeDiaryStore.uid(this));render();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}
 private void manage(){AppWidgetManager m=AppWidgetManager.getInstance(this);ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(Class<?> type:CustomWidgetProvider.TYPES)for(int id:m.getAppWidgetIds(new ComponentName(this,type))){JSONObject p=CustomWidgetStore.widget(this,id);ids.add(id);labels.add((p==null?"Set up widget":("money".equals(p.optString("type"))?"Money":"Shortcuts"))+" · "+CustomWidgetProvider.size(this,id));}if(ids.isEmpty()){Toast.makeText(this,"No custom widgets on the home screen yet",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Your custom widgets").setItems(labels.toArray(new String[0]),(d,index)->startActivity(new Intent(this,CustomWidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,ids.get(index)))).setNegativeButton("Cancel",null).show();}
 private void finishWidget(){try{syncName();if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID&&plan.getString("size").equals(CustomWidgetProvider.size(this,widgetId))){CustomWidgetStore.configure(this,widgetId,plan);CustomWidgetProvider.update(this,widgetId);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();return;}
   AppWidgetManager m=AppWidgetManager.getInstance(this);String layout=CustomWidgetStore.saveLayout(this,plan);if(!m.isRequestPinAppWidgetSupported()){new AlertDialog.Builder(this).setTitle("Layout saved").setMessage("Long-press your home screen, open Widgets → MANTRA, select Custom widget in this size, then load this saved layout.").setPositiveButton("OK",null).show();return;}
   Intent callback=new Intent(this,CustomWidgetPinnedReceiver.class).setData(Uri.parse("mantra-widget://pinned/"+layout)).putExtra("layoutId",layout);PendingIntent done=PendingIntent.getBroadcast(this,0,callback,PendingIntent.FLAG_UPDATE_CURRENT|(android.os.Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));Bundle extras=new Bundle();extras.putParcelable(AppWidgetManager.EXTRA_APPWIDGET_PREVIEW,CustomWidgetProvider.views(this,0,plan,new Bundle()));boolean requested=m.requestPinAppWidget(CustomWidgetProvider.component(this,plan.getString("size")),extras,done);if(requested)Toast.makeText(this,"Confirm placement on your home screen. This layout is saved if you cancel.",Toast.LENGTH_LONG).show();else Toast.makeText(this,"Your launcher could not add the widget. Use its widget picker and load the saved layout.",Toast.LENGTH_LONG).show();
  }catch(Exception e){error(e);}}
